def _load_questions():
    data = {}
    for row in QUESTIONS.strip().splitlines():
        fields = row.split('|')
        if len(fields) != 4:
            raise ValueError(f'invalid question line: {fields[0]}')
        name, *questions = fields
        if name in data or any(not q.endswith('?') or len(q) < 20 for q in questions):
            raise ValueError(f'duplicate or malformed questions: {name}')
        data[name] = tuple(questions)
    if set(data) != set(SITE_PRACTICE):
        raise ValueError('question subjects do not match editorial subjects')
    if len(set(q for row in data.values() for q in row)) != 288:
        raise ValueError('repeated questions')
    return MappingProxyType(data)

SITE_QUESTIONS = _load_questions()
